// The explanatory text is paired with actual outputs generated by build-method-examples.py.
const g=(question,unit,fields,calculation,read,next,packages)=>({question,unit,fields,calculation,read,next,packages});
export const methodGuides={
 describe:g('12人の操作時間。典型的な時間はどのくらいで、長く迷った人はいる？','1行＝1人。時間を同じ課題・同じ単位で測ります。',[['time_sec','課題を終えるまでの時間（秒）。']], '件数・平均・中央値・標本標準偏差・最小値・最大値を計算する。',['countは12人、mean（平均）は約20.67秒、median（中央値）は18.5秒です。','50秒かかった人がいるため、平均は中央値より大きくなっています。std（標準偏差）は約9.87秒で、人ごとのばらつきを表します。'],'50秒の元記録を確かめ、ヒストグラムや個々の値の図で分布を見る。理由なく削除しない。','pandas'),
 crosstab:g('在宅勤務をする人と、オフィス勤務の人では、選ぶ椅子が違う？','1行＝回答者1人。勤務場所と選んだ椅子を、同じ人について記録します。',[['work','home＝在宅、office＝オフィス。'],['chair','選んだ椅子AまたはB。']], '勤務場所×選んだ椅子の人数を数え、勤務場所ごとの人数を分母にした割合を出す。',['homeでは8人中6人がAを選び、75%。officeでは8人中3人で37.5%です。','人数の表から「それぞれの勤務場所で、何人中何人か」が分かります。この表だけでは、勤務場所が選択の原因だとは言えません。'],'各行の人数と割合を一緒に報告する。集団に広げて違いを調べるなら、対象の独立性と標本の集め方を確認する。','pandas'),
 welch:g('画面Aを使った6人と、Bを使った別の6人。平均時間はどのくらい違う？','1行＝1人。各人はA・Bの片方だけを使い、参加者どうしが独立している比較です。',[['screen','使った画面AまたはB。'],['time_sec','操作時間（秒）。']], '独立した2群について、等分散を仮定しない両側Welchのt検定を行う。差はA−B、信頼区間は95%。',['Aの平均25秒、Bは20秒。平均差A−Bは5秒なので、この標本ではBのほうが速い方向です。','平均差の95%信頼区間は約0.39〜9.61秒。tは約2.42、pは約0.036です。差が0という仮説を検討する数値で、Bが優れている確率ではありません。'],'平均差と信頼区間を秒で報告し、個々の値・外れ値・群の集め方も確認する。','pandas scipy'),
 paired:g('同じ12人でAとBを試した。人ごとの差を平均すると、どれだけ速くなる？','1行＝同じ人のA・Bの組。同じ人の測定値を別の行にずらさないことが重要です。',[['time_A_sec','その人がAを使った時間（秒）。'],['time_B_sec','同じ人がBを使った時間（秒）。']], '人ごとのA−Bを計算し、両側の対応のあるt検定と平均差の95%信頼区間を出す。',['平均差A−Bは5秒。個人内の差の標準偏差は約7.21秒です。','t(11)は約2.402、pは約0.0351。平均差の95%信頼区間は約0.42〜9.58秒です。この区間は個人差の95%が収まる範囲ではありません。'],'人ごとの線を結んだ図と差の分布に戻る。順番による練習・疲れの影響を検討する。','pandas scipy'),
 anova:g('画面A・B・Cを別々の人が使った。3つの平均が全部同じと考えてよい？','1行＝1人。ここでは各人が一つの画面だけを使う、一元配置の例です。',[['screen','画面の種類A・B・C。'],['time_sec','操作時間（秒）。']], '一元配置分散分析で、画面の違いによるばらつきと、同じ画面内のばらつきを比べる。',['C(screen)が画面の効果、Residualが同じ条件内に残ったばらつきです。sum_sqは平方和、dfは自由度、PR(>F)がp値です。','F(2,18)＝6、pは約0.0101。「A・B・Cの平均はすべて同じ」という仮説を検討します。どの組が違うかは、この表だけでは決まりません。'],'各群の平均は30・26・22秒。あらかじめ決めた比較や多重比較の方法で、必要な組を調べる。二元・三元では要因と交互作用をモデルに追加する。','pandas statsmodels'),
 ranks:g('1〜5段階の満足度。別々の人が使ったAとBで、高い評点が出やすいのはどちら？','1行＝1人。ここでは独立した2群に使うMann–WhitneyのU検定を例にします。',[['screen','その人が評価した画面AまたはB。'],['rating','満足度1〜5。高いほど満足。']], '順位を使うMann–WhitneyのU検定を、両側・同順位を補正した漸近法で行う。',['Uは12.5、pは約0.040です。どちらの群に大きな評点が出やすいかを調べる結果です。','これはどんなデータでも「中央値だけの差」を検定する方法ではありません。値の分布の形も確認します。'],'同じ人の比較なら対応に合う方法、3条件以上なら条件数に合う方法に変更する。AIに独立・対応と条件数を必ず伝える。','pandas scipy'),
 categorical:g('Aで20人中12人、Bで20人中18人が成功。成功率に違いはある？','この表は集計済み。1行＝画面、セル＝人数です。AとBの参加者は別々です。',[['record_id','画面AまたはB。'],['success','成功した人数。'],['failure','失敗した人数。']], '成功・失敗の人数から、独立性のカイ二乗検定（Pearson、連続性補正なし）とFisherの両側正確確率検定を計算し、成功率も出す。',['標本の成功率はAが60%、Bが90%で、差は30ポイントです。','この例ではカイ二乗のpが約0.028、Fisherのpが約0.065です。近似や計算方法が違うと境界付近の判断も変わります。小さいpが出る方法を後から選ぶための比較ではありません。'],'人数と割合の差をまず報告する。解析方法は表の大きさ・期待度数・設計から事前に選ぶ。同じ人のA・BならMcNemarを検討する。','pandas scipy'),
 mcnemar:g('同じ24人がAとBを使った。失敗から成功に変わった人は、逆方向より多い？','1行＝同じ人のA・Bでの成功／失敗の組。人数だけ別々に集計せず、対応を残します。',[['A','Aで成功なら1、失敗なら0。'],['B','同じ人がBで成功なら1、失敗なら0。']], 'A失敗→B成功とA成功→B失敗の人数を数え、McNemarの両側正確検定を行う。',['A失敗→B成功が10人、逆が2人です。両方失敗3人、両方成功9人も記録しますが、方向の違いの検定に使うのは10対2です。','pは約0.0386。標本ではBで成功に変わった人が多く、その方向の偏りを調べています。'],'実施順による練習効果や、A・Bで課題の難しさを揃えたかも確かめる。','pandas statsmodels'),
 correlation:g('座面が高い椅子ほど、評価も高いという関係はある？','1行＝1脚の椅子。同じ椅子の高さと評価を横に並べます。',[['height_cm','座面の高さ（cm）。'],['rating','その椅子の評価値。この例では連続量として扱う練習。']], '散布図を確認し、Pearsonの積率相関係数と、Spearmanの順位相関係数を計算する。',['Pearsonのrは約0.980、Spearmanのρも約0.982で、この例では高い椅子ほど評価が高い関係です。','相関が高くても「高くすれば評価が上がる」という因果関係は証明できません。曲線や外れ値は散布図で確認します。'],'評価が順序尺度か量として扱えるかを考え、問いに合う係数を選ぶ。係数だけでなく散布図も示す。','pandas scipy'),
 regression:g('椅子の幅と重さから、価格をどのくらい説明できる？','1行＝1脚。価格と、その椅子の幅・重さを記録します。',[['width_cm','幅（cm）。'],['weight_kg','重さ（kg）。'],['price_yen','価格（円）。目的変数。']], '価格を目的変数、幅と重さを説明変数にした重回帰。係数と95%信頼区間を出し、残差を確認する。',['推定式は、価格＝5,000＋200×幅＋800×重さです。幅が1cm大きいと、重さが同じ条件では価格が200円高い関係を表します。','重さ1kgあたりは800円。係数は原因の大きさとは限りません。Interceptは幅も重さも0の切片で、この例では実際の椅子としての意味は持ちません。'],'残差の形と多重共線性を確認する。未知の椅子を予測したい場合は、学習に使っていないデータで予測誤差を測る。','numpy pandas statsmodels'),
 logistic:g('練習を何回したかによって、操作に成功する確率は変わる？','1行＝1人。結果は成功／失敗の2種類です。',[['practice','練習した回数。'],['success','成功1、失敗0。']], '成功を目的変数にしたロジスティック回帰分析で、回数ごとの予測確率とオッズ比を出す。',['予測確率は練習0回で約11%、3回で約82%です。これはモデルによる推定で、全員がその結果になるという意味ではありません。','オッズ比は約3.29。1回増えたとき「成功のオッズ」が約3.29倍になる推定です。成功確率が3.29倍になる、という意味ではありません。'],'成功・失敗の件数と予測確率を確認する。新しい人への予測では、別データで正解率だけでなく確率の当たり方も確かめる。','numpy pandas statsmodels'),
 mixed:g('同じ人のA・B評価を使い、人ごとの速さの違いを考慮して画面差を調べたい。','1行＝1人の1条件での測定。同じ人が2行に登場するので、personで結び付けます。',[['person','参加者ID。繰り返した測定で同じIDを使う。'],['screen','画面AまたはB。'],['time_sec','時間（秒）。']], '画面を固定効果、人ごとの切片を変量効果とする線形混合モデルを計算する。',['B−Aは約−5.94秒。参加者による基本的な速さを考慮して、Bが短い方向の推定です。','個人差の分散は人ごとの基本的な速さの違い、残差分散はそれでも説明しきれない違いを表します。60行でも参加者は30人です。'],'人ごとに画面の効果も違いそうなら、傾きも変えるモデルを検討する。収束したかと残差を確認する。','numpy pandas statsmodels'),
 pca:g('幅・奥行き・重さの3項目を、少数の軸でまとめるとどうなる？','1行＝1脚。すべての椅子で同じ3項目を測ります。',[['width_cm／depth_cm','幅と奥行き（cm）。'],['weight_kg','重さ（kg）。']], '単位の違いを揃えるため各列を標準化し、PCAで2軸にまとめる。重み・寄与率・椅子ごとの得点を出す。',['PC1では3項目の重みがほぼ同じ方向なので、「全体的に大きく重い」という軸と読めそうです。','寄与率は、元のばらつきのどのくらいをその軸が表したか。予測の正解率ではありません。椅子ごとの主成分得点を使うと、位置の図にできます。'],'項目の重みと元の測定値を照らし、軸に名前を付ける。左右の符号は反転しても同じ解析です。','pandas scikit-learn'),
 factor:g('6つの質問は、「操作の分かりやすさ」と「見た目の好み」のような共通の特徴にまとまる？','1行＝1人、1列＝質問への回答。例は計算用に作った連続的な評定値です。',[['見つけやすい／迷わない／操作が分かる','操作に関わる3項目。'],['形が好き／色が好き／魅力を感じる','見た目に関わる3項目。']], '各質問を標準化し、2因子の探索的因子分析を行う。この例ではバリマックス回転（varimax rotation）で軸を読みやすくする。',['因子負荷量の絶対値が大きい質問ほど、その因子との関わりが強い結果です。操作の3項目と、見た目の3項目が別々の因子にまとまっています。','因子の1・2や正負は入れ替わることがあります。マイナスだから悪い質問、とは読みません。独自分散は共通因子で説明されない部分です。'],'因子数を2と決めた理由を別に検討する。実際の1〜5段階の回答では、順序尺度に合う相関・推定法も検討する。','numpy pandas scikit-learn'),
 ca:g('製品A・B・Cと、「落ち着く・軽快・力強い」の選ばれ方を地図にしたい。','1行＝製品、1列＝印象語、各セル＝選んだ人数の度数表です。',[['record_id','製品A・B・C。'],['落ち着く／軽快／力強い','その製品で、その印象語を選んだ人数。']], '度数表に対応分析を適用し、行・列の主座標と軸ごとの慣性の割合を出す。',['Aでは「落ち着く」が20人、ほかは5人ずつ。この偏りに対応した座標が出ます。座標をプロットして、製品ごとの選ばれ方の違いを見ます。','座標は円や秒のような測定単位ではありません。行と列を同時に描く図では、製品と印象語の単純な距離を一般的な類似度として読みません。元の比率も照らします。'],'出現人数が少ないカテゴリーの影響と各軸の情報量を確認する。座標の向きや軸の番号自体に意味を付けない。','numpy pandas'),
 mca:g('場所・素材・スタイルという、複数のカテゴリー回答をまとめたい。','1行＝1人、列＝別々の質問。どの人がどの選択肢を選んだかを残します。',[['place','home＝自宅、office＝オフィス。'],['material','wood＝木、steel＝金属。'],['style','soft＝柔らかな印象、sharp＝鋭い印象。']], '全カテゴリーの指示行列に対応分析を適用し、補正なしMCAのカテゴリー座標と慣性の割合を出す。',['place_homeとmaterial_woodは第1軸の同じ側にあります。自宅と木を一緒に選ぶ傾向を、元の回答でも確認できます。','数量化理論III類と対応する分析です。カテゴリーや人を軸上に配置する方法で、自動的にグループの正解が決まるわけではありません。'],'珍しい回答の影響や、採用した軸でどこまで表せているかを確認する。補正あり・なしで慣性の割合が変わるので計算方法を記録する。','numpy pandas'),
 mds:g('製品どうしの「違って見える度合い」から、位置の図を作りたい。','行も列も同じ製品A〜D。セル＝その2製品の非類似度です。',[['A〜D','大きいほど違う。AからBとBからAが同じ、対角が0の表。']], '非類似度を入力した計量MDSで2次元座標を求め、stressで再現のずれを確認する。',['A−BとC−Dは非類似度1なので、各ペアが近い位置になります。A−Cは3なので、それより離れる配置になります。','stressは、元の非類似度と配置上の距離のずれを表す指標です。この実行例は正規化しないstressを出します。座標の向きは回転しても同じ意味です。'],'類似度（大きいほど似る）をそのまま非類似度として入れない。2次元で十分か、距離の再現を確認する。','numpy pandas scikit-learn'),
 cluster:g('価格と重さが似ている椅子を、グループにまとめたい。','1行＝1脚。正解のグループは与えず、測定した特徴から分けます。',[['price_yen','価格（円）。'],['weight_kg','重さ（kg）。']], '価格と重さを標準化し、k平均法（k-means法）で2群に分ける。所属番号と各群の元の単位での平均を出す。',['この例では、安く軽い3脚と、高く重い3脚に分かれます。clusterの0・1は単なる名前で、優劣や順位ではありません。','今回は「2群にする」とこちらが指定した結果です。自然界に必ず2種類あると発見したわけではありません。'],'群の数や使う項目、標準化の方法を変えたときの安定性を確かめ、元のデータで各群の特徴を説明する。','pandas scikit-learn'),
 conjoint:g('形・素材・価格の組み合わせを評価してもらい、好みに関わる属性を調べたい。','1行＝1人が一つの製品案に付けた評点。ここでは別々の人による評定型の例です。',[['material／shape','steel・wood、square・roundの組み合わせ。'],['price_yen','提示した価格10,000円または20,000円。'],['rating','その案に付けた評点。大きいほど好み。']], '評定型の例として、評点を素材・形・価格のカテゴリーで回帰し、基準水準からの評点の差を求める。',['金属→木は＋1.5点、丸→四角は−0.5点、1万円→2万円は−1点です。これらが、このモデルでの部分効用の違いに対応します。','切片5.5は「金属・丸・1万円」の予測評点。0をどこに置くかで表示は変わりますが、水準間の差は読み取れます。'],'実際に選択肢から一つ選ぶ選択型のデータには、同じ評定型回帰をそのまま使わない。同じ人の複数評価では参加者IDも扱う。','numpy pandas statsmodels'),
 sem:g('「分かりやすさ」が「満足度」に関わる、という仮説を複数の質問で調べたい。','1行＝1人。質問への回答に加えて、どの質問で何を測るかと、どの向きの関係を考えるかを先に決めます。',[['u1・u2・u3','分かりやすさを測る3項目の連続的な評定値。'],['s1・s2・s3','満足度を測る3項目。例は連続データとして生成。']], '2つの潜在変数を各3項目で測り、満足度←分かりやすさのパスを置くSEMを推定する。標準化係数と適合度を出す。',['Satisfaction ~ Usabilityは「満足度を分かりやすさで説明する」というパスです。Est. Stdが標準化した係数です。','CFI・TLI・RMSEAは、仮説の構造がデータとどのくらい合うかを確かめる材料です。適合がよいだけで、矢印の向きが因果関係だと証明されるわけではありません。'],'質問が想定した概念を測るか、収束・負の分散・識別可能性を確認する。結果を見て都合よく矢印を増やさない。','numpy pandas semopy'),
 forest:g('椅子の幅と重さから、新しい椅子の価格を予測したい。','1行＝1脚。説明変数と、正解になる価格をそろえます。',[['width_cm／weight_kg','予測に使う幅と重さ。'],['price_yen','実際の価格。']], '90脚で学習し、使わなかった30脚で評価する。決定木・ランダムフォレストと、平均価格だけを答える基準モデルを比較する。',['テストMAEは、未知の椅子について予測価格が平均で何円ずれたかです。小さいほど、この評価データでは誤差が少ない結果です。','学習MAEだけが小さくても、新しい椅子への予測がよいとは言えません。変数の重要度を、価格の原因の大きさと読み替えることもできません。'],'評価用データを見て何度も調整せず、調整用と最後の評価用を分ける。現実的に許せる誤差額と比べる。','numpy pandas scikit-learn'),
 neural:g('2つの測定特徴から成功／失敗を予測する、小さなニューラルネットワークを試したい。','1行＝1回の独立した観測。特徴量2列と、そのときの成功／失敗を用意します。',[['feature_1／feature_2','予測に使う2つの連続量。この例は計算練習用の架空の特徴。'],['success','正解ラベル。失敗0、成功1。']], 'この例では多層パーセプトロン（MLP：Multilayer Perceptron）を使う。120件で標準化とネットワークの学習を行い、残り40件で評価する。多数派を答えるだけの基準と正解率を比べ、混同行列も出す。',['テスト正解率は、学習に使わなかった40件の何割を正しく予測したかです。学習正解率と区別します。','混同行列では「実際0なのに予測1」など、間違え方が分かります。全体の正解率だけでよいモデルと決めないために見ます。'],'予測を間違えた場合の影響を考え、必要なら感度・適合率・確率の校正も評価する。同じ人のデータは人ごとに分割する。','numpy pandas scikit-learn'),
 quant1:g('形や素材のようなカテゴリーから、操作時間を説明したい。','1行＝1人の測定。説明する結果は時間という量、説明変数はカテゴリーです。',[['shape','square＝四角、round＝丸。'],['material','steel＝金属、wood＝木。'],['time_sec','時間（秒）。']], '「丸かどうか」「木かどうか」を0・1の列にして回帰する（ダミー変数化）。形や素材ごとに、予測する時間を何秒増減させるかという点数＝カテゴリースコアを出す。',['全体平均25秒に、形と素材のスコアを足すと予測できます。丸は−3、木は−2なので「丸・木」は25−3−2＝20秒です。','四角と丸の差は6秒、金属と木の差は4秒です。スコアのプラスは時間を長くする方向であり、よい評価という意味ではありません。'],'カテゴリーに1・2を付けても、そのまま量として回帰しない。実際の不均等なデータでは、単純な群平均との差ではなくモデルからスコアを計算する。','pandas statsmodels'),
 quant2:g('経験や利用場所から、Aを選ぶ人・選ばない人を判別したい。','1行＝1人。正解となるグループが既にあり、説明変数もカテゴリーです。',[['experience','new＝初心者、experienced＝経験者。'],['place','home＝自宅、office＝オフィス。'],['choose_A','Aを選ぶ1、選ばない0。']], '「初心者か」「自宅で使うか」を0・1の列にして、Aを選ぶ人と選ばない人を分ける点数を求める。ここではダミー変数を使う線形判別分析で、II類に対応する計算をする。60人で計算方法を作り、残りの20人で確かめる。',['この実装では、当てはまるカテゴリーの重みを足し、切片を加えると判別得点になります。「経験者・オフィス」なら0.639＋0.496−0.010≒1.125。0より大きければ「Aを選ぶ」、小さければ「選ばない」と判別します。','テスト正解率0.7は、計算方法を作るときに使わなかった20人中14人を正しく判別できた、という意味です。残り6人は外れています。得点の基準や大きさは実装で変わるため、他ソフトの数値とはそのまま比べません。'],'III類のようにグループを探す目的とは違う。既知のグループを判別する問いか確認する。カテゴリーの少人数・未出現にも注意する。','numpy pandas scikit-learn'),
 quant3:g('グループの正解は決めず、複数のカテゴリー回答のパターンを見たい。','1行＝1人、1列＝質問。予測したい数値や、正解のグループを決めずに、回答どうしの関係を調べます。',[['place','home＝自宅、office＝オフィス。'],['material','wood＝木、steel＝金属。'],['style','soft＝柔らかな印象、sharp＝鋭い印象。']], '「自宅を選んだか」「木を選んだか」などを0・1の列にし、回答パターンから各カテゴリーを図に置く座標を計算する。ここでは対応する多重対応分析（MCA）を使う。',['出てくるのは、カテゴリーを図に置くための座標です。place_homeとmaterial_woodが第1軸の同じ側にあり、元の回答でも一緒に選ばれやすいかを確認します。','多重対応分析（MCA）と対応する方法です。正解ラベルを予測するII類とは、目的も出力も異なります。'],'カテゴリーの位置、元の人数、軸の情報量を一緒に読む。軸の正負が逆でも配置の関係が同じなら解釈は変わらない。','numpy pandas'),
 quant4:g('製品A〜Dについて「どの2つが似ているか」の表から、位置を作りたい。','行も列も製品A〜D。「AとBはどのくらい似ているか」を、全ペアについて数値にした表を用意します。この似ている度合いを親近性と呼びます。ここではA→BとB→Aが同じ表を使います。',[['A〜D','各製品ペアの親近性。A−Bは9、C−Dは8で似ている。対角は0。']], '似ているという関係をできるだけ配置に反映させるように、各製品の座標を計算する。全点が同じ場所に集まるだけでは比較できないので、それを避ける条件を置く。下の例では横・縦の2つの座標を出す。',['軸1の座標はA・Bが0.5、C・Dが−0.5です。横方向を見ると、この2組が分かれます。固有値は座標の計算で出る値で、製品のよさやp値ではありません。まず、座標を図にして元の親近性と見比べます。','元の親近性は大きいほど似ている値です。大きいほど違う非類似度を入力する計量MDSと、目的や計算を混同しません。座標の反転や回転自体は解釈を変えません。'],'どのように親近性を集めたかを説明し、元のペアの関係を配置が表しているか確認する。この実行例は対称な正の親近性を使う場合です。','numpy pandas'),
};
